fn solve(word: Vec<char>) -> Vec<char> {
    // Two flags to track if we've seen a letter from Set A or Set B
    let mut has_a = false;
    let mut has_b = false;

    for c in word {
        match c {
            // Set A letters:
            'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N'
            | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z' => {
                has_a = true;
            }
            // Set B letters:
            'B' | 'C' | 'D' | 'G' | 'J' | 'O' | 'P' | 'Q' | 'R'
            | 'S' | 'U' => {
                has_b = true;
            }
            // We assume input is always 'A'..'Z', so no other branch is needed.
            _ => {}
        }
        // Early exit: if we've seen both kinds, we already know the answer is "NO"
        if has_a && has_b {
            return "NO".chars().collect();
        }
    }

    // If we saw letters from exactly one set, it's "YES"; otherwise "NO"
    if (has_a && !has_b) || (has_b && !has_a) {
        "YES".chars().collect()
    } else {
        "NO".chars().collect()
    }
}

